"""
Shared test fixtures for RELAY-SOLARIS tool tests.

Provides mock Houdini objects for testing without live Houdini.
"""

import pytest
from unittest.mock import MagicMock, patch, PropertyMock
from collections import defaultdict


class MockParm:
    """Mock Houdini parameter."""

    def __init__(self, name, value=None):
        self._name = name
        self._value = value

    def name(self):
        return self._name

    def set(self, value):
        self._value = value

    def eval(self):
        return self._value

    def evalAsString(self):
        return str(self._value) if self._value is not None else ""


class MockNodeType:
    """Mock Houdini node type."""

    def __init__(self, name, category_name="Lop"):
        self._name = name
        self._category_name = category_name

    def name(self):
        return self._name

    def category(self):
        mock_cat = MagicMock()
        mock_cat.name.return_value = self._category_name
        return mock_cat


class MockNode:
    """Mock Houdini node with children, parms, and wiring."""

    def __init__(self, path, type_name="null", parent=None):
        self._path = path
        self._type = MockNodeType(type_name)
        self._parent = parent
        self._children = {}
        self._parms = {}
        self._inputs = []
        self._outputs = []
        self._user_data = {}
        self._name = path.rsplit("/", 1)[-1] if "/" in path else path
        self._destroyed = False

    def path(self):
        return self._path

    def name(self):
        return self._name

    def setName(self, name, unique_name=False):
        self._name = name

    def type(self):
        return self._type

    def parent(self):
        return self._parent

    def children(self):
        return list(self._children.values())

    def node(self, relative_path):
        """Find a child by relative path."""
        return self._children.get(relative_path)

    def createNode(self, type_name, name=None):
        node_name = name or type_name
        child_path = f"{self._path}/{node_name}"
        child = MockNode(child_path, type_name, parent=self)
        # Give it some default parms based on type
        child._parms = _default_parms_for_type(type_name)
        self._children[node_name] = child
        return child

    def parm(self, name):
        return self._parms.get(name)

    def parms(self):
        return list(self._parms.values())

    def setInput(self, index, node):
        while len(self._inputs) <= index:
            self._inputs.append(None)
        self._inputs[index] = node
        if node and hasattr(node, '_outputs'):
            node._outputs.append(self)

    def inputs(self):
        return [i for i in self._inputs if i is not None]

    def outputs(self):
        return self._outputs

    def setUserData(self, key, value):
        self._user_data[key] = value

    def userData(self, key):
        return self._user_data.get(key)

    def layoutChildren(self):
        pass

    def moveToGoodPosition(self):
        pass

    def isNetwork(self):
        return len(self._children) > 0

    def destroy(self):
        self._destroyed = True
        if self._parent and self._name in self._parent._children:
            del self._parent._children[self._name]


def _default_parms_for_type(type_name):
    """Return a dict of default MockParms for common node types."""
    common = {
        "primitive": {"primpath": MockParm("primpath"), "primtype": MockParm("primtype"), "primkind": MockParm("primkind")},
        "sopimport": {"soppath": MockParm("soppath"), "primpath": MockParm("primpath")},
        "sopcreate": {"primpath": MockParm("primpath")},
        "camera": {"primpath": MockParm("primpath")},
        "materiallibrary": {"primpath": MockParm("primpath")},
        "karmaphysicalsky": {"primpath": MockParm("primpath")},
        "karmarendersettings": {"engine": MockParm("engine"), "resx": MockParm("resx"), "resy": MockParm("resy"), "camera": MockParm("camera")},
        "usdrender_rop": {"outputimage": MockParm("outputimage")},
        "componentgeometry": {"soppath": MockParm("soppath"), "purpose": MockParm("purpose")},
        "componentmaterial": {},
        "componentoutput": {"name": MockParm("name"), "filepath": MockParm("filepath")},
        "componentgeometryvariants": {},
        "explorevariants": {},
        "subnet": {},
        "reference": {"filepath1": MockParm("filepath1"), "primpath": MockParm("primpath"), "destpath": MockParm("destpath")},
        "usdimport": {"filepath": MockParm("filepath"), "unpacktopolygons": MockParm("unpacktopolygons")},
        "xform": {"scale": MockParm("scale"), "rx": MockParm("rx"), "ry": MockParm("ry"), "rz": MockParm("rz")},
        "matchsize": {"justifyy": MockParm("justifyy")},
        "polyreduce": {"percentage": MockParm("percentage")},
        "output": {},
    }
    return common.get(type_name, {})


class MockUndoGroup:
    """Context manager for mock hou.undos.group()."""
    def __init__(self, name=""):
        self.name = name
    def __enter__(self):
        return self
    def __exit__(self, *args):
        pass


@pytest.fixture
def mock_stage():
    """Provide a mock /stage LOP network."""
    return MockNode("/stage", "lopnet")


@pytest.fixture
def mock_hou(mock_stage):
    """Patch hou module globally for tool tests."""
    mock_hou_module = MagicMock()
    mock_hou_module.node.side_effect = lambda path: mock_stage if path == "/stage" else None
    mock_hou_module.undos.group.side_effect = lambda name="": MockUndoGroup(name)
    mock_hou_module.lopNodeTypeCategory.return_value = MagicMock()
    mock_hou_module.nodeType.return_value = None  # Default: componentbuilder doesn't exist
    mock_hou_module.copyNodesTo = lambda nodes, parent: [
        parent.createNode(n.type().name(), f"{n.name()}_copy") for n in nodes
    ]

    return mock_hou_module

